<?php
declare(strict_types=1);

function flashes(): void {
    foreach($_SESSION['flashes'] ?? [] as $f) echo '<div class="notice notice-'.e($f['kind']).'" role="status">'.icon($f['kind']==='error'?'clock':'check').'<span>'.e($f['message']).'</span></div>';
    unset($_SESSION['flashes']);
}
function head(string $title, string $bodyClass=''): void { ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#123f39"><meta name="author" content="Softnic Solutions"><link rel="author" href="https://softnicsolutions.com"><title><?=e($title)?> · <?=e(setting('business_name','BookNest'))?></title><link rel="icon" href="assets/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/app.css"><script src="assets/app.js" defer></script></head><body class="<?=e($bodyClass)?>"><a href="#main" class="skip-link">Skip to content</a>
<?php }
function foot(): void { echo '</body></html>'; }
function public_header(): void { ?>
<header class="public-header"><a class="brand" href="<?=e(url())?>"><span class="brand-mark"><?=icon('calendar')?></span><span><?=e(setting('business_name','BookNest'))?></span></a><nav aria-label="Main"><a href="<?=e(url('book'))?>">Book an appointment</a><a class="button button-small button-ghost" href="<?=e(url(user()?'dashboard':'login'))?>"><?=icon('lock')?><?=user()?'Dashboard':'Business login'?></a></nav></header>
<?php }
function public_footer(): void { ?>
<footer class="public-footer"><span>Booking made simple.</span><span class="powered"><span class="mini-mark"><?=icon('calendar')?></span> BookNest by <a href="https://softnicsolutions.com" target="_blank" rel="noopener" title="Softnic Solutions — softnicsolutions.com">Softnic Solutions</a></span><?php if(setting('contact_email')!==''):?><a href="mailto:<?=e(setting('contact_email'))?>">Contact us</a><?php endif;?></footer>
<?php }
function admin_start(string $title, string $active, string $description=''): void {
    $u=require_user();head($title,'admin-body'); ?>
<aside class="sidebar" id="sidebar"><a class="brand brand-light" href="<?=e(url('dashboard'))?>"><span class="brand-mark"><?=icon('calendar')?></span><span>BookNest<span class="brand-caption">BUSINESS DESK</span></span></a><div class="workspace"><span class="workspace-avatar"><?=e(short_name(setting('business_name')))?></span><div><strong><?=e(setting('business_name'))?></strong><small>Your workspace</small></div><span class="workspace-dot"></span></div><div class="nav-label">WORKSPACE</div><nav aria-label="Dashboard"><?php foreach([['dashboard','grid','Overview'],['appointments','calendar','Appointments'],['services','service','Services'],['staff','people','Team'],['schedule','clock','Availability']] as [$page,$ic,$name]):?><a class="nav-item <?=$active===$page?'active':''?>" href="<?=e(url($page))?>"><?=icon($ic)?><span><?=$name?></span><?php if($active===$page):?><span class="active-dot"></span><?php endif;?></a><?php endforeach;?><div class="nav-label nav-label-spaced">MANAGE</div><a class="nav-item <?=$active==='settings'?'active':''?>" href="<?=e(url('settings'))?>"><?=icon('settings')?>Business settings</a><a class="nav-item <?=$active==='account'?'active':''?>" href="<?=e(url('account'))?>"><?=icon('lock')?>Your account</a></nav><div class="sidebar-bottom"><a class="booking-link" href="<?=e(url('book'))?>" target="_blank" rel="noopener"><?=icon('external')?><span>Open booking page<small>See what your customers see</small></span></a><div class="owner-row"><span class="owner-avatar"><?=e(short_name($u['name']))?></span><div><strong><?=e($u['name'])?></strong><small>Business owner</small></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="logout"><button class="icon-button" title="Sign out" aria-label="Sign out"><?=icon('logout')?></button></form></div></div></aside>
<div class="admin-shell"><header class="admin-topbar"><div class="topbar-left"><button class="icon-button mobile-menu" type="button" data-menu aria-controls="sidebar" aria-expanded="false" aria-label="Toggle navigation"><?=icon('grid')?></button><span class="breadcrumb">Workspace<span>/</span><strong><?=e($title)?></strong></span></div><div class="topbar-right"><span class="today-label"><?=icon('calendar')?><?=e(local_now()->format('D, j M Y'))?></span><span class="topbar-avatar"><?=e(short_name($u['name']))?></span></div></header><main class="admin-main" id="main"><div class="page-heading"><div><p class="eyebrow">YOUR BUSINESS, IN SYNC</p><h1><?=e($title)?></h1><?php if($description):?><p class="muted"><?=e($description)?></p><?php endif;?></div><a class="button" href="<?=e(url('book'))?>" target="_blank" rel="noopener"><?=icon('plus')?>New booking</a></div><?php flashes();
}
function admin_end(): void { ?><footer class="admin-footer"><span>BookNest · <a href="https://softnicsolutions.com" target="_blank" rel="noopener">Softnic Solutions</a></span><span><?=e(setting('timezone','Asia/Karachi'))?></span></footer></main></div><?php foot(); }
function empty_state(string $title, string $message, string $ic='calendar'): void { echo '<div class="empty-state"><span class="empty-icon">'.icon($ic).'</span><h3>'.e($title).'</h3><p>'.e($message).'</p></div>'; }
function field(string $name,string $label,mixed $value='',string $type='text',bool $required=true,string $hint=''): void { ?>
<label class="field"><span><?=e($label)?><?php if(!$required):?> <small>optional</small><?php endif;?></span><input name="<?=e($name)?>" type="<?=e($type)?>" value="<?=e($value)?>" <?=$required?'required':''?> <?=$type==='password'?'autocomplete="current-password"':''?>><?php if($hint):?><small class="field-hint"><?=e($hint)?></small><?php endif;?></label>
<?php }
function textarea_field(string $name,string $label,string $value='',int $max=1200): void { ?><label class="field"><span><?=e($label)?></span><textarea name="<?=e($name)?>" maxlength="<?=$max?>" rows="3"><?=e($value)?></textarea></label><?php }
function select_field(string $name,string $label,array $options,mixed $selected): void { ?><label class="field"><span><?=e($label)?></span><select name="<?=e($name)?>"><?php foreach($options as $v=>$label):?><option value="<?=e($v)?>" <?=(string)$v===(string)$selected?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><?php }
function appointment_table(array $bookings): void {
    if(!$bookings){empty_state('No appointments here yet','Share your booking page to start filling your calendar.');return;} ?>
<div class="table-scroll"><table class="data-table"><thead><tr><th>Customer</th><th>Service & team</th><th>Date & time</th><th>Status</th><th class="align-right">Amount</th><th><span class="sr-only">Open</span></th></tr></thead><tbody><?php foreach($bookings as $b):?><tr><td><a class="customer-cell" href="<?=e(url('appointment',['id'=>$b['id']]))?>"><span class="avatar"><?=e(short_name($b['client_name']))?></span><span><strong><?=e($b['client_name'])?></strong><small><?=e($b['reference'])?></small></span></a></td><td><strong><?=e($b['service_name'])?></strong><small><?=e($b['staff_name'])?></small></td><td><strong><?=e(local_date($b['starts_at'],'j M Y'))?></strong><small><?=e(local_date($b['starts_at'],'g:i a'))?> · <?=(int)$b['duration_minutes']?> min</small></td><td><?=status_badge($b['status'])?></td><td class="align-right"><strong><?=e(money((int)$b['price_minor'],$b['currency_code']))?></strong></td><td><a class="icon-button" href="<?=e(url('appointment',['id'=>$b['id']]))?>" aria-label="View booking <?=e($b['reference'])?>"><?=icon('chevron')?></a></td></tr><?php endforeach;?></tbody></table></div>
<?php }
